import{_ as n,l,o as e,c as i,v as t,p as s,x as r,d as h,i as b,S as C}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"控制变量对欧式","description":"","frontmatter":{"title":"控制变量对欧式","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/cv-european.md","filePath":"quant/cv-european.md","lastUpdated":1789023840000}'),E={name:"quant/cv-european.md"};function m(p,a,d,c,B,_){const o=l("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="控制变量对欧式" tabindex="-1">控制变量对欧式 <a class="header-anchor" href="#控制变量对欧式" aria-label="Permalink to &quot;控制变量对欧式&quot;">​</a></h1><div class="epigraph"><p>在同一条风险中性路径上计算目标支付与一个期望已知的相关支付，用回归系数减去偏差之后再平均；欧式香草因此常把 Black–Scholes 闭式当成几乎免费的方差锚。</p><footer>—— Glasserman, Monte Carlo Methods in Financial Engineering, 2004；Boyle, Options: A Monte Carlo Approach, Journal of Financial Economics, 1977</footer></div><p><a href="/quant/tree-early-exercise">上一课</a>把重组树上的美式写成每个节点 \\(\\max(g,\\text{风险中性续持})\\)；一维香草用树或 PDE，路径依赖不重组时改 LSM。方差缩减课已经把对偶、控制变量与重要性采样放在同一约束下。缺口是把控制变量落到欧式支付：闭式香草为什么是默认 \\(C\\)、\\(\\beta\\) 怎么估、几何亚式如何控算术亚式。本课写这一构造，不重讲树上的执行区域。美式 LSM 的策略偏差不在此消除；障碍与稀有事件优先重要性采样。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>欧式 \\(Y=e^{-rT}g(S_T)\\) 或路径泛函但行权仍在 \\(T\\)。朴素平均的标准误是 \\(s/\\sqrt{N}\\)。欧式的 \\(g\\) 往往与某个<strong>可解析定价</strong>的支付高度相关：同一 \\(S_T\\) 上的看涨与 Black–Scholes 看涨、算术平均与几何平均、篮子与其几何平均。控制变量构造</p> \\[Y(\\beta)=Y-\\beta\\bigl(C-\\mathbb{E}[C]\\bigr), \\]<p>\\(\\mathbb{E}[Y(\\beta)]=\\mathbb{E}[Y]\\) 当且仅当 \\(\\mathbb{E}[C]\\) 正确。最优 \\(\\beta^*=\\mathrm{Cov}(Y,C)/\\mathrm{Var}(C)\\)，方差缩减因子为 \\(1-\\rho_{Y,C}^2\\)。问题是找 \\(\\rho\\) 接近 1 且 \\(\\mathbb{E}[C]\\) 廉价精确的 \\(C\\)，并在有限 \\(N\\) 上估 \\(\\beta\\) 而不引入明显偏差。</p><p>欧式相对美式的优势正在这里：到期支付是路径（或终点）的已知函数，没有「回归出来的停时」插在中间，\\(Y\\) 与 \\(C\\) 的相关是结构上的。把同一技巧套到 LSM 的最终现金流上，只能降评估方差，早执行规则仍然次优。</p><h3 id="闭式必须与模拟是同一测度、同一离散" tabindex="-1">闭式必须与模拟是同一测度、同一离散 <a class="header-anchor" href="#闭式必须与模拟是同一测度、同一离散" aria-label="Permalink to &quot;闭式必须与模拟是同一测度、同一离散&quot;">​</a></h3><p>\\(C\\) 若是连续 Black–Scholes，\\(\\mathbb{E}[C]\\) 用公式；模拟若用 Euler 离散的局部波动或随机波动，则 \\(Y\\) 与 \\(C\\) 不是同一过程上的支付，\\(\\rho\\) 仍可能高，但「同一 \\(S_T\\)」要定义清楚：通常 \\(C\\) 用这条路径上的 \\(S_T\\) 代入 BS 公式，当作相关的随机变量，其期望仍用 BS 闭式——此时 \\(C\\) 的期望对应的是<strong>对数正态</strong>，不是你模拟的模型。无偏性仍成立，因为减的是 \\(C-\\mathbb{E}_{\\mathrm{BS}}[C]\\)，\\(Y\\) 的期望不变；降方差靠的是 \\(S_T\\) 仍与对数正态高度相关。若错误地把 \\(\\mathbb{E}[C]\\) 改成「同一 MC 估出来的均值」，控制项期望为零的样本版本互相抵消，方差几乎不降。</p><p><span class="marginnote">\\(\\mathbb{E}[C]\\) 必须来自闭式、级数或独立的高精度引擎（COS/FFT），不能来自正在平均的那批路径。Heston 香草当控制时，应用特征函数价，而不是再用一套粗 MC。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>单控制：路径上同时算 \\(Y_i,C_i\\)，样本协方差给 \\(\\hat\\beta\\)，再平均 \\(Y_i-\\hat\\beta(C_i-\\mathbb{E}[C])\\)。\\(\\beta\\) 用全样本时引入 \\(O(1/N)\\) 偏差，欧式大 \\(N\\) 下通常可忽略；严谨可分批。经典配对：</p><ul><li>香草看涨模拟（检验、或无闭式的模型）用同一 \\(K,T\\) 的 BS 作为 \\(C\\)。</li><li>算术亚式用几何亚式闭式（Kemna–Vorst）：\\(\\rho\\) 常在 0.9 以上，方差降一个数量级很常见。</li><li>篮子、最大值期权用几何平均或单资产香草的组合。</li><li>终点 \\(S_T\\) 本身：\\(\\mathbb{E}[S_T]=S_0 e^{(r-q)T}\\)，对近似线性的支付有用，对带 \\(\\max(\\cdot,0)\\) 的香草弱于 BS 控制。</li></ul><p>多控制：\\(C\\) 为向量，\\(\\beta\\) 为多元回归系数。例如同时用 ATM 与目标 \\(K\\) 的 BS，或用 \\(S_T\\) 与 \\(S_T^2\\)。边际收益递减，且 \\(\\beta\\) 估计的噪声随维数升。Delta 鞅控制：沿路径用 BS \\(\\Delta\\) 对冲，残差是离散对冲误差，期望仍为期权价减去组合初值；这是控制变量的连续时间版本，实现成本高于终点 \\(C\\)。</p><h3 id="heston-与局部波动上的控制" tabindex="-1">Heston 与局部波动上的控制 <a class="header-anchor" href="#heston-与局部波动上的控制" aria-label="Permalink to &quot;Heston 与局部波动上的控制&quot;">​</a></h3><p>模拟 <a href="/quant/heston">Heston</a> 路径给欧式，控制可选：同一参数的特征函数价格（此时 \\(C\\) 是常数！——常数控制方差减零，无意义）或「把本路径的 \\(S_T\\) 代入 BS，波动用某种等效」。常数不能当 \\(C\\)。正确做法是选一条<strong>路径级</strong>随机变量：例如用瞬时方差积分 \\(\\int v_t dt\\) 构造的对数正态代理，再代入 BS，期望用特征函数或用代理的解析均值。更稳妥：用几何布朗、\\(\\sigma^2=\\theta\\) 或 \\(v_0\\) 的 BS 作为 \\(C(S_T)\\)，期望用 BS 公式。局部波动路径与 Dupire 香草闭式不存在，仍可用 BS 当 \\(C\\)。相关随微笑变陡而下降，翼部产品降方差有限，应改重要性采样。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>\\(Y(\\beta)\\) 是 \\(Y\\) 对 \\(C\\) 做线性回归的残差再平移回正确均值。\\(\\rho\\to 1\\) 时残差趋向 0，一条路径就定价格——几何亚式控算术亚式接近这一理想。\\(\\rho=0\\) 时最优 \\(\\beta=0\\)，控制无益但无害（若 \\(\\mathbb{E}[C]\\) 正确）。\\(\\beta\\) 估错只影响方差，不影响无偏性（全样本 \\(\\hat\\beta\\) 的高阶项除外）。这与重要性采样不同：IS 估错漂移会让权重崩溃，期望仍对但方差更大；控制估错 \\(\\beta\\) 最坏回到朴素方差。</p><p>欧式支付对终点单调时，对偶与控制可叠：先 \\((Y(Z)+Y(-Z))/2\\) 再减 \\(C\\)。二者降的是不同部分：对偶降对称噪声，控制降与闭式共有的部分。计算预算应计入两次支付；若 \\(\\rho\\) 已经极高，对偶的边际常很小。</p><p><span class="marginnote">\\(\\beta=1\\) 在 \\(Y\\) 与 \\(C\\) 同量纲、几乎同一支付时可用，避免估 \\(\\beta\\) 的小样本噪声。算术对几何亚式通常估 \\(\\beta\\) 更值得。不要把 \\(\\beta\\) 解释成对冲比：它是方差最优的回归系数，可以远大于 1。</span></p>',21)),(e(),s(C,null,{default:r(()=>[b(o,{id:"mermaid-78",class:"mermaid",graph:"flowchart%20TD%0A%20%20Path%5B%22%E5%90%8C%E4%B8%80%20Q%20%E8%B7%AF%E5%BE%84%22%5D%20--%3E%20Y%5B%22%E7%9B%AE%E6%A0%87%E6%AC%A7%E5%BC%8F%E6%94%AF%E4%BB%98%20Y%22%5D%0A%20%20Path%20--%3E%20C%5B%22%E6%8E%A7%E5%88%B6%E6%94%AF%E4%BB%98%20C%22%5D%0A%20%20Closed%5B%22%E9%97%AD%E5%BC%8F%20E%5BC%5D%22%5D%20--%3E%20CV%5B%22Y%20-%20%CE%B2(C-E%5BC%5D)%22%5D%0A%20%20Y%20--%3E%20CV%0A%20%20C%20--%3E%20CV%0A%20%20Beta%5B%22%CE%B2%20%3D%20Cov%2FVar%20%E6%88%96%E5%9B%9E%E5%BD%92%22%5D%20--%3E%20CV%0A%20%20CV%20--%3E%20Avg%5B%22%E5%B9%B3%E5%9D%87%3A%20%E6%97%A0%E5%81%8F%E3%80%81%E6%9B%B4%E5%B0%8F%E6%96%B9%E5%B7%AE%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h3 id="标准误、有效样本量与验收" tabindex="-1">标准误、有效样本量与验收 <a class="header-anchor" href="#标准误、有效样本量与验收" aria-label="Permalink to &quot;标准误、有效样本量与验收&quot;">​</a></h3><p>报告 \\(\\widehat{\\mathrm{Var}}(Y(\\hat\\beta))\\) 时，若 \\(\\beta\\) 由同批估计，标准误略乐观，大 \\(N\\) 可忽略。验收：Black–Scholes 世界里用 BS 当控制，残差应接近机器零（同一 \\(S_T\\)、同一公式），这是代码测试。Heston 上控制后的标准误应下降，价格应仍落在 COS 价的未控制置信区间里——若均值挪了，是 \\(\\mathbb{E}[C]\\) 写错或测度错。深虚值欧式 \\(\\rho\\) 可以很高但 \\(Y\\) 几乎全零，相对误差仍大，控制代替不了改抽样。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>路径依赖若没有近亲闭式，控制变弱：回望、障碍的指示函数与香草相关有限。离散观察亚式要用对应观察日的几何平均闭式，连续几何公式会对错 \\(\\mathbb{E}[C]\\)。美式不能用欧式 BS 当控制来「修正提前行权」——减的是错误产品。随机利率下 \\(C\\) 的贴现必须与 \\(Y\\) 一致，否则相关被贴现噪声稀释。</p><p>不要用控制掩盖 Euler 偏差：弱收敛误差在 \\(\\mathbb{E}[Y]\\) 里，减 \\(C-\\mathbb{E}[C]\\) 不去掉它。不要把特征函数价格当路径级 \\(C\\)（那是常数）。引用 Boyle 1977 是早期 MC；控制变量的系统论述见 Glasserman 2004。几何亚式闭式见 Kemna and Vorst, 1990。</p><p><span class="marginnote">本篇是方差缩减在欧式上的专章，不是定价理论。无套利与测度仍由 <a href="/quant/risk-neutral-pricing">风险中性</a> 与模拟动力学负责。Heston 香草的生产价格应走傅里叶，MC 加控制用于路径产品或验收。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>欧式控制变量用路径级 \\(C\\) 与精确 \\(\\mathbb{E}[C]\\)，最优 \\(\\beta\\) 为回归系数，方差因子 \\(1-\\rho^2\\)。</li><li>\\(\\mathbb{E}[C]\\) 必须闭式或独立高精度；同批 MC 估均值等于没有控制。</li><li>默认锚：BS 对香草、几何亚式对算术亚式；Heston 要用路径函数而非常数模型价。</li><li>无偏性在 \\(\\mathbb{E}[C]\\) 正确时成立；\\(\\beta\\) 估错主要伤方差。不消除离散偏差与美式策略偏差。</li><li>深虚值与障碍优先改抽样；控制与对偶可叠，预算要计入额外支付。</li><li>出处：Glasserman, 2004；Boyle, <em>JFE</em>, 1977；几何亚式见 Kemna and Vorst, 1990；总览见 <a href="/quant/mc-variance-reduction">方差缩减</a>。</li></ul>',8))])}const T=n(E,[["render",m]]);export{S as __pageData,T as default};
